      "items": {
        "type": "string"
      },
      "description": "選択では解決できず情報提供が必要な欠落"
    },
    "branches": {
      "type": "array",
      "maxItems": 5,
      "items": {
        "type": "object",
        "properties": {
          "question_point": {
            "type": "string"
          },
          "anchor_words": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string"
            },
            "description": "原文の連続部分文字列をそのまま・可能な限り最長フレーズで"
          },
          "downstream_impact": {
            "type": "string"
          },
          "options": {
            "type": "array",
            "minItems": 2,
            "maxItems": 3,
            "items": {
              "type": "object",
              "properties": {
                "label": {
                  "type": "string"
                },
                "thumbnail_description": {
                  "type": "string"
                },
                "px200_rationale": {
                  "type": "string",
                  "description": "200pxで判別できる根拠"
                }
              },
              "required": [
                "label",
                "thumbnail_description",
                "px200_rationale"
              ]
            }
          },
          "default_if_unresolved": {
            "type": "string"
          }
        },
        "required": [
          "question_point",
          "anchor_words",
          "downstream_impact",
